namespace ghidra.app.plugin.core.data;





using docking.action;
using docking.action;
using ghidra.app.context;
using ghidra.app.context;
using ghidra.app.util.datatype;
using ghidra.framework.plugintool;
using ghidra.program.model.data;
using ghidra.program.model.listing;
using ghidra.util.data.DataTypeParser;

/**
 * An action that allows the user to change or select a data type.
 */
public class ChooseDataTypeAction : ListingContextAction {

	private DataPlugin plugin;
	private static readonly KeyStroke KEY_BINDING = KeyStroke.getKeyStroke(KeyEvent.VK_T, 0);
	private static string ACTION_NAME = "Choose Data Type";

	public ChooseDataTypeAction(DataPlugin plugin) : base(ACTION_NAME, plugin.getName(), KeyBindingType.SHARED)
    {
		this.plugin = plugin;

		initKeyStroke(KEY_BINDING);
	}

	private void initKeyStroke(KeyStroke keyStroke) {
		if (keyStroke == null) {
			return;
		}

		setKeyBindingData(new KeyBindingData(keyStroke));
	}

	/* @Override */
	protected void actionPerformed(ListingActionContext context) {
		DataType dataType = getDataType(context);
		if (dataType != null) {
			plugin.createData(dataType, context, false, true);
		}
	}

	private DataType getDataType(ListingActionContext context) {
		PluginTool tool = plugin.getTool();
		Data data = plugin.getDataUnit(context);
		int noSizeRestriction = -1;
		DataTypeSelectionDialog selectionDialog = new DataTypeSelectionDialog(tool,
			data.getProgram().getDataTypeManager(), noSizeRestriction, AllowedDataTypes.ALL);
		DataType dt = data.getDataType();
		selectionDialog.setInitialDataType(dt);
		tool.showDialog(selectionDialog);
		return selectionDialog.getUserChosenDataType();
	}

	/* @Override */
	protected bool isEnabledForContext(ListingActionContext context) {
		return plugin.isCreateDataAllowed(context);
	}
}
